const shopPaymentsAnalysis = await tools.semantic_query({analysis: "SHOP/payments", operation: "flowmap", from: {name: "submit"}, all: true});

// Extract the retained analysis ID
const analysisId = shopPaymentsAnalysis.analyses[0].id;

// Now use the retained ID to query the flow map
const flowMapResult = await tools.semantic_query({analysis: analysisId, operation: "flowmap", from: {name: "submit"}, all: true});

// Find the specific map where rebate < 0 is false (i.e., rebate >= 0)
let targetMap = null;
for (const map of flowMapResult.analyses[0].flowMaps) {
    if (map.from.name === "submit") {
        // Check assumptions for this map
        const hasRebateAssumption = map.assumptions.some(a => a.expression.includes("rebate"));
        if (hasRebateAssumption) {
            targetMap = map;
            break;
        }
    }
}

// If no specific map found, use the first one with rebate assumption
if (!targetMap && flowMapResult.analyses[0].flowMaps.length > 0) {
    targetMap = flowMapResult.analyses[0].flowMaps[0];
}

// Trace the rebate parameter to argument 1 of save under the assumption that rebate < 0 is false
const traceResult = await tools.semantic_trace({
    analysis: analysisId,
    from: {kind: "method", name: targetMap.from.name, parameter: "rebate"},
    to: {kind: "call", name: "save", argument: 1},
    assumptions: [{expression: "rebate < 0", holds: false}],
    all: true
});

// Extract the required fields
const entry = targetMap.from.name;
const exitCall = traceResult.sides[0].data.paths[0].nodes.find(n => n.kind === "call" && n.name === "save");
const sinkExpression = traceResult.sides[0].data.paths[0].nodes.find(n => n.kind === "sink");
const controlAssumption = targetMap.assumptions.find(a => a.expression.includes("rebate"));
const dataAssumption = traceResult.assumptions.find(a => a.expression.includes("rebate"));

// Check if the map is complete
const mapComplete = targetMap.complete;

// Get evidence views (links)
const evidenceViews = [];
if (targetMap.nodes.length > 0) {
    evidenceViews.push({name: "entry-exit-map", url: `http://127.0.0.1:4000/show/${analysisId}`});
}
if (traceResult.sides[0].data.paths.length > 0) {
    evidenceViews.push({name: "value-trace", url: `http://127.0.0.1:4000/show/${analysisId}/trace`});
}

// Return the result as JSON
return {
    entry,
    exitCall: exitCall ? exitCall.name : null,
    sinkExpression: sinkExpression ? sinkExpression.expression : null,
    controlAssumption: controlAssumption ? controlAssumption.expression : null,
    dataAssumption: dataAssumption ? dataAssumption.expression : null,
    behaviorVerified: traceResult.proof.status === "verified",
    mapComplete,
    evidenceViews
};

